import {ADDITIONAL_ACTIVITIES} from './quiz-additional-model.mjs';
import {createAdditionalWidgets} from './quiz-additional-ui.mjs';
import {DISPLAY_TYPES,SINGLE_TYPES,MATRIX_TYPES} from './quiz-model.mjs';
import {mathHTML,mathText,mathsPalette,bindMaths} from './quiz-maths.mjs';
const providers=['Google Forms','Microsoft Forms','Desmos','GeoGebra','PhET','Microsoft 365','Google Drive','Web resource'];
export function createQuizWidgets({e,option,api}){
 const select=(name,label,values,value)=>`<label class="vle-field">${label}<select data-q="${name}">${values.map(v=>option(Array.isArray(v)?v[0]:v,Array.isArray(v)?v[1]:v,value)).join('')}</select></label>`;
 const input=(name,label,value='',extra='')=>`<label class="vle-field">${label}<input data-q="${name}" value="${e(value??'')}" ${extra}></label>`;
 const text=(name,label,value='',hint='')=>`<label class="vle-field">${label}<textarea data-q="${name}" rows="3" maxlength="10000">${e(value??'')}</textarea>${hint?'<small>'+e(hint)+'</small>':''}</label>`;
 const imageHTML=image=>image?`<figure class="quiz-question-image"><img src="data:${e(image.mime||'image/png')};base64,${image.data}" alt="${e(image.alt||'Question image')}"><figcaption>${e(image.alt||'')}</figcaption></figure>`:'';
 const extra=createAdditionalWidgets({e,option,input,text,imageHTML,filesFromInput,api});
 const choice=q=>[...SINGLE_TYPES,'checkboxes'].includes(q.type);
 function restoredPassage(q){return q.blankAnswers?q.passage.replace(/\[\[(\d+)\]\]/g,(_,n)=>'[['+q.blankAnswers[Number(n)-1].join('|')+']]'):q.passage||'';}
 function config(q,i){if(ADDITIONAL_ACTIVITIES[q.type])return extra.config(q);let html='';
  if(choice(q)){const items=q.type==='truefalse'?['True','False']:q.options||['',''];html=`<div class="vle-answer-key"><strong>Answer options & key</strong><small>Select the correct answer${q.type==='checkboxes'?'s (all must match)':''}. $...$ renders maths in options.</small>${items.map((v,j)=>`<div class="quiz-option-editor"><div class="vle-option-row"><input type="${q.type==='checkboxes'?'checkbox':'radio'}" name="correct-${i}" data-correct value="${j}" aria-label="Correct option ${j+1} for question ${i+1}" ${Array.isArray(q.correct)?q.correct.includes(j)?'checked':'':q.correct===j?'checked':''}><input data-option value="${e(v)}" maxlength="500" required aria-label="Option ${j+1} for question ${i+1}" ${q.type==='truefalse'?'readonly':''}>${items.length>2&&q.type!=='truefalse'?`<button type="button" class="text-button" data-quiz-remove-option="${i}" data-option-index="${j}">×</button>`:''}</div>${q.optionImages?.[j]?imageHTML(q.optionImages[j]):''}<label class="quiz-option-image-upload">Option image<input type="file" data-option-image="${j}" accept="image/png,image/jpeg,image/webp"></label>${q.optionImages?.[j]?`<button type="button" class="text-button" data-remove-option-image="${j}">Remove option image</button>`:''}</div>`).join('')}${items.length<20&&q.type!=='truefalse'?`<button type="button" class="text-button" data-quiz-add-option="${i}">＋ Add option</button>`:''}</div>`;}
  else if(q.type==='short'||q.type==='paragraph')html=text('acceptedAnswers',q.type==='short'?'Accepted answers (optional, one per line)':'Model answer / marking guidance (teacher only)',q.type==='short'?(q.acceptedAnswers||[]).join('\n'):q.guidance||'',q.type==='short'?'Leave blank for teacher marking. Exact matching ignores case and repeated spaces.':'Written responses are marked by the teacher.');
  else if(q.type==='math')html=select('mathMode','Marking mode',[['expression','Algebra / working — teacher review'],['numeric','Numeric answer with tolerance']],q.mathMode||'expression')+input('numericKey','Numeric answer (numeric mode)',q.numericKey??'','placeholder="e.g. 0.5 or 1/2"')+input('tolerance','Tolerance (numeric mode)',q.tolerance??0,'type="number" min="0" step="any"')+text('acceptedAnswers','Accepted algebraic answers (optional, one per line)',(q.acceptedAnswers||[]).join('\n'),'Text matches only; algebraic equivalence and method marks need teacher review.');
  else if(['missing','dragwords'].includes(q.type))html=text('passage','Passage with gaps',restoredPassage(q),'Write [[answer]] or [[answer|alternative]] for each gap. Correct gaps earn proportional marks.')+(q.type==='dragwords'?text('wordBank','Extra word-bank choices (one per line)',(q.wordBank||[]).join('\n'),'Correct words are added automatically; add distractors here.'):'');
  else if(q.type==='ranking')html=text('items','Items in the correct order (one per line)',q.correct?q.correct.map(n=>q.options[n]).join('\n'):(q.options||[]).join('\n'),'Students reorder a shuffled list by dragging or using the arrow buttons.');
  else if(q.type==='matching')html=text('pairs','Matching pairs (one per line)',q.pairs?.length?q.pairs.map(p=>p.left+' => '+p.right).join('\n'):q.rows?.length?q.rows.map((v,j)=>v+' => '+q.options[q.correct[j]]).join('\n'):'','Example: CPU => Processes instructions. Students connect pairs; correct pairs earn proportional marks.');
  else if(MATRIX_TYPES.includes(q.type))html=text('rows','Row labels (one per line)',(q.rows||[]).join('\n'))+text('items','Column labels (one per line)',(q.options||[]).join('\n'))+text('gridKey','Answer key (optional; column numbers per row)',q.correct?q.correct.map(v=>Array.isArray(v)?v.map(n=>n+1).join(','):v+1).join('\n'):'','Use 1-based column numbers, one row per line. Checkbox grids accept 1,3. Leave blank for teacher marking.')+`<label class="quiz-check"><input type="checkbox" data-q="uniqueColumns" ${q.uniqueColumns?'checked':''}> Limit each column to one selection</label>`;
  else if(['scale','rating','nps'].includes(q.type))html=`<div class="vle-form-grid">${input('minimum','Scale starts',q.minimum??(q.type==='rating'?1:0),'type="number" min="0" max="1"')}${input('maximum','Scale ends',q.maximum??(q.type==='nps'?10:5),'type="number" min="2" max="10"')}${input('lowLabel','Low label',q.lowLabel)}${input('highLabel','High label',q.highLabel)}${input('scaleKey','Correct value (optional)',q.correct??'','type="number"')}</div>`+(q.type==='rating'?select('ratingIcon','Rating symbol',[['star','Stars'],['heart','Hearts'],['thumb','Thumbs up']],q.ratingIcon||'star'):'')+'<p class="vle-note">Use 0 points for a survey. NPS always uses 0–10.</p>';
  else if(['date','datetime','time','duration'].includes(q.type))html=text('acceptedAnswers','Accepted answer (optional)',(q.acceptedAnswers||[]).join('\n'),'Dates: YYYY-MM-DD. Date/time: YYYY-MM-DDTHH:MM. Time: HH:MM. Duration: HHHH:MM:SS. Blank = teacher review.');
  else if(q.type==='file')html=select('maxFiles','Maximum files',['1','2','3'],String(q.maxFiles||1))+text('allowedExtensions','Allowed extensions, separated by commas',(q.allowedExtensions||['pdf','docx','png','jpg']).join(','),'pdf, txt, csv, docx, xlsx, pptx, png, jpg, jpeg, webp, mp3, wav, mp4, webm. 1 MB per file; 8 MB total per submission.');
  else if(['video','external'].includes(q.type))html=select('provider','Resource provider',providers,q.provider||'Web resource')+input('resource','HTTPS activity / video link',q.resource||'','type="url" placeholder="https://…"')+'<p class="vle-note">Opens the linked resource. School OAuth / LTI connections and automatic provider score imports are not connected in this demo.</p>';
  else html='<p class="vle-note">This is a content block. It has no response and awards no points.</p>';
  return html;
 }
 function readConfig(el,q){if(ADDITIONAL_ACTIVITIES[q.type])return extra.readConfig(el,q);const value=name=>el.querySelector('[data-q="'+name+'"]')?.value??'',list=name=>value(name).split('\n').map(x=>x.trim()).filter(Boolean);const r={...q};
  if(choice(q)){r.options=[...el.querySelectorAll('[data-option]')].map(x=>x.value);const key=[...el.querySelectorAll('[data-correct]:checked')].map(x=>Number(x.value));r.correct=q.type==='checkboxes'?key:key[0];}
  if(q.type==='short'||['math','date','datetime','time','duration'].includes(q.type))r.acceptedAnswers=list('acceptedAnswers');
  if(q.type==='paragraph')r.guidance=value('acceptedAnswers');
  if(q.type==='math'){r.mathMode=value('mathMode');r.numericKey=value('numericKey');r.tolerance=Number(value('tolerance'));}
  if(['missing','dragwords'].includes(q.type)){r.passage=value('passage');delete r.blankAnswers;r.wordBank=list('wordBank');}
  if(q.type==='ranking'){r.options=list('items');delete r.correct;}
  if(q.type==='matching'){r.pairs=list('pairs').map(line=>{const [left,...rest]=line.split('=>');return{left:left.trim(),right:rest.join('=>').trim()};});}
  if(MATRIX_TYPES.includes(q.type)){r.rows=list('rows');r.options=list('items');r.correct=list('gridKey').map(line=>q.type==='checkboxgrid'?line.split(',').map(x=>Number(x.trim())-1):Number(line)-1);r.uniqueColumns=el.querySelector('[data-q="uniqueColumns"]').checked;}
  if(['scale','rating','nps'].includes(q.type)){r.minimum=Number(value('minimum'));r.maximum=Number(value('maximum'));r.lowLabel=value('lowLabel');r.highLabel=value('highLabel');r.ratingIcon=value('ratingIcon');r.correct=value('scaleKey')===''?undefined:Number(value('scaleKey'));}
  if(q.type==='file'){r.maxFiles=Number(value('maxFiles'));r.allowedExtensions=value('allowedExtensions').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);}
  if(['video','external'].includes(q.type)){r.provider=value('provider');r.resource=value('resource');}
  return r;
 }
 function common(q){return `<details class="quiz-media-settings" ${q.mediaOpen?'open':''}><summary>Image, maths & extra instructions</summary>${text('description','Description / help text',q.description)}<label class="vle-field">Teacher image / diagram (PNG, JPEG, WebP, up to 1 MB)<input type="file" data-question-image accept="image/png,image/jpeg,image/webp"></label>${imageHTML(q.image)}${q.image?'<button type="button" class="text-button" data-remove-question-image>Remove image</button>':''}${input('imageAlt','Image description / alt text',q.image?.alt||'')}${text('formula','Maths formula (LaTeX)',q.formula,'Examples: \\frac{1}{2}, x^{2}, \\sqrt{x}. Inline $...$ also works in questions and choices.')}${mathsPalette('formula')}<div class="quiz-math-preview" data-formula-preview>${mathHTML(q.formula)}</div>${text('feedbackCorrect','Feedback for correct answers',q.feedback?.correct)}${text('feedbackIncorrect','Feedback for other answers',q.feedback?.incorrect)}</details>`;}
 function studentWidget(q,value,locked){if(ADDITIONAL_ACTIVITIES[q.type])return extra.studentWidget(q,value,locked);const disabled=locked?'disabled':'',readonly=locked?'readonly':'';
  if(DISPLAY_TYPES.includes(q.type))return q.type==='video'?`<a class="btn" href="${e(q.resource)}" target="_blank" rel="noopener noreferrer">Open video ↗</a>`:'';
  if(choice(q)){if(q.type==='dropdown')return `<select aria-label="Choose an answer" data-answer-value ${disabled}>${option('','Choose…',value??'')}${q.options.map((v,j)=>option(j,v,value)).join('')}</select>`;return q.options.map((v,j)=>`<label class="vle-student-option"><input type="${q.type==='checkboxes'?'checkbox':'radio'}" name="answer-${q.id}" value="${j}" ${Array.isArray(value)?value.includes(j)?'checked':'':value===j?'checked':''} ${disabled}>${mathText(v)}${imageHTML(q.optionImages?.[j])}</label>`).join('');}
  if(['missing','dragwords'].includes(q.type)){const values=value||[],parts=q.passage.split(/(\[\[\d+\]\])/);return (q.type==='dragwords'?`<div class="quiz-word-bank" aria-label="Word bank">${q.wordBank.map(w=>`<button type="button" draggable="${!locked}" data-drag-word="${e(w)}" ${disabled}>${e(w)}</button>`).join('')}</div><small>Drag a word into a gap, or select a gap and choose a word. You can also type.</small>`:'')+`<div class="quiz-gap-passage">${parts.map(p=>{const m=p.match(/^\[\[(\d+)\]\]$/);return m?`<input class="quiz-gap" data-gap="${Number(m[1])-1}" aria-label="Missing word ${m[1]}" value="${e(values[Number(m[1])-1]||'')}" ${readonly}>`:mathText(p);}).join('')}</div>`;}
  if(q.type==='ranking'){const order=Array.isArray(value)&&value.length?value:q.options.map((_,i)=>i);return `<ol class="quiz-ranking" aria-label="Ranking order">${order.map(n=>`<li draggable="${!locked}" data-rank-item="${n}"><span class="quiz-drag-handle">⠿</span><span>${mathText(q.options[n])}</span><button type="button" data-rank-move="-1" aria-label="Move ${e(q.options[n])} up" ${disabled}>↑</button><button type="button" data-rank-move="1" aria-label="Move ${e(q.options[n])} down" ${disabled}>↓</button></li>`).join('')}</ol><small>Drag items to order them. Arrow buttons work with a keyboard or touch.</small>`;}
  if(q.type==='matching'){const rows=q.rows.map((v,i)=>`<div class="quiz-match-row"><button type="button" draggable="${!locked}" data-match-left="${i}" aria-label="Connect ${e(v)}" ${disabled}>${mathText(v)}</button><select data-match-select="${i}" aria-label="Match for ${e(v)}" ${disabled}>${option('','Not connected',value?.[i]??'')}${q.options.map((t,j)=>option(j,t,value?.[i])).join('')}</select></div>`).join('');return `<small>Drag from a left-hand item to a target, click a pair, or use the dropdowns.</small><div class="quiz-match-panel"><svg class="quiz-match-lines" aria-hidden="true"></svg><div class="quiz-match-left">${rows}</div><div class="quiz-match-right">${q.options.map((v,j)=>`<button type="button" data-match-right="${j}" ${disabled}>${mathText(v)}</button>`).join('')}</div></div>`;}
  if(MATRIX_TYPES.includes(q.type))return `<div class="table-wrap"><table class="data-table quiz-matrix"><thead><tr><th></th>${q.options.map(v=>'<th>'+mathText(v)+'</th>').join('')}</tr></thead><tbody>${q.rows.map((row,i)=>`<tr data-matrix-row="${i}"><th scope="row">${mathText(row)}</th>${q.options.map((col,j)=>`<td><input type="${q.type==='checkboxgrid'?'checkbox':'radio'}" name="${q.id}-row-${i}" value="${j}" aria-label="${e(row+' — '+col)}" ${Array.isArray(value?.[i])?value[i].includes(j)?'checked':'':value?.[i]===j?'checked':''} ${disabled}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  if(['scale','rating','nps'].includes(q.type)){const icon=q.ratingIcon==='heart'?'♥':q.ratingIcon==='thumb'?'👍':'★';return `<div class="quiz-scale">${Array.from({length:q.maximum-q.minimum+1},(_,i)=>i+q.minimum).map(n=>`<label><input type="radio" name="answer-${q.id}" value="${n}" ${value===n?'checked':''} ${disabled}><span>${q.type==='rating'?icon+' ':''}${n}</span></label>`).join('')}</div><div class="quiz-scale-labels"><span>${e(q.lowLabel)}</span><span>${e(q.highLabel)}</span></div>`;}
  if(q.type==='file')return `<label class="vle-field">Upload response (up to ${q.maxFiles} files, 1 MB each)<input data-answer-files type="file" ${q.maxFiles>1?'multiple':''} accept="${q.allowedExtensions.map(x=>'.'+x).join(',')}" ${disabled}></label><small>${(value||[]).map(f=>e(f.name)).join(' · ')||'No saved files'}</small>`;
  const external=q.type==='external'?`<p><a class="btn" href="${e(q.resource)}" target="_blank" rel="noopener noreferrer">Open ${e(q.provider)} activity ↗</a></p><small>Submit your response below. Provider scores are not imported automatically.</small>`:'';
  if(q.type==='paragraph')return `<textarea aria-label="Written answer" data-answer-value maxlength="10000" ${readonly}>${e(value||'')}</textarea>`;
  const type={date:'date',datetime:'datetime-local',time:'time'}[q.type]||'text';return external+`<input data-answer-value ${q.type==='math'?'data-math-answer':''} type="${type}" aria-label="${e(q.type==='math'?'Maths answer':'Answer')}" value="${e(value||'')}" maxlength="2000" ${q.type==='duration'?'placeholder="HHH:MM:SS"':''} ${readonly}>`+(q.type==='math'?(locked?'':mathsPalette('answer'))+`<div class="quiz-math-preview" data-math-answer-preview>${mathHTML(value||'')}</div>`:'');
 }
 async function filesFromInput(input){if(!input?.files?.length)return null;return Promise.all([...input.files].map(f=>new Promise((resolve,reject)=>{if(f.size>1048576){reject(Error('Each file must be 1 MB or smaller.'));return;}const reader=new FileReader();reader.onerror=()=>reject(Error('Could not read '+f.name));reader.onload=()=>resolve({name:f.name,data:String(reader.result).split(',')[1]});reader.readAsDataURL(f);})));}
 async function readAnswer(el,q,previous){if(ADDITIONAL_ACTIVITIES[q.type])return extra.readAnswer(el,q,previous);if(DISPLAY_TYPES.includes(q.type))return null;if(q.type==='file')return await filesFromInput(el.querySelector('[data-answer-files]'))??previous??[];if(q.type==='dropdown'){const v=el.querySelector('[data-answer-value]').value;return v===''?null:Number(v);}if(q.type==='checkboxes')return [...el.querySelectorAll('input:checked')].map(x=>Number(x.value));if([...SINGLE_TYPES,'scale','rating','nps'].includes(q.type))return el.querySelector('input:checked')?Number(el.querySelector('input:checked').value):null;if(['missing','dragwords'].includes(q.type))return [...el.querySelectorAll('[data-gap]')].map(x=>x.value);if(q.type==='ranking')return [...el.querySelectorAll('[data-rank-item]')].map(x=>Number(x.dataset.rankItem));if(q.type==='matching')return [...el.querySelectorAll('[data-match-select]')].map(x=>x.value===''?null:Number(x.value));if(MATRIX_TYPES.includes(q.type))return [...el.querySelectorAll('[data-matrix-row]')].map(row=>q.type==='checkboxgrid'?[...row.querySelectorAll('input:checked')].map(x=>Number(x.value)):row.querySelector('input:checked')?Number(row.querySelector('input:checked').value):null);return el.querySelector('[data-answer-value]')?.value||'';}
 function answerText(q,v){if(ADDITIONAL_ACTIVITIES[q.type])return extra.answerText(q,v);if(q.type==='file')return(v||[]).map(f=>f.name).join(', ');if(choice(q))return(Array.isArray(v)?v:[v]).filter(Number.isInteger).map(n=>q.options[n]).join(', ');if(q.type==='ranking')return(v||[]).map(n=>q.options[n]).join(' → ');if(q.type==='matching'||MATRIX_TYPES.includes(q.type))return q.rows.map((row,i)=>row+': '+(Array.isArray(v?.[i])?v[i].map(n=>q.options[n]).join(', '):Number.isInteger(v?.[i])?q.options[v[i]]:'—')).join('\n');if(Array.isArray(v))return v.join(' / ');return String(v??'');}
 let observers=[];
 function bindStudent(root){extra.bind(root);observers.forEach(o=>o.disconnect());observers=[];bindMaths(root);let drag=null,selectedGap=null,selectedLeft=null;
  const draw=panel=>{const svg=panel.querySelector('svg'),bounds=panel.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${bounds.width} ${bounds.height}`);svg.replaceChildren();panel.querySelectorAll('[data-match-select]').forEach(sel=>{if(sel.value==='')return;const left=panel.querySelector('[data-match-left="'+sel.dataset.matchSelect+'"]'),right=panel.querySelector('[data-match-right="'+sel.value+'"]'),a=left.getBoundingClientRect(),b=right.getBoundingClientRect(),line=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [k,v]of Object.entries({x1:a.right-bounds.left,y1:a.top+a.height/2-bounds.top,x2:b.left-bounds.left,y2:b.top+b.height/2-bounds.top,stroke:['#317d73','#a66b30','#745aa2','#346aa0'][Number(sel.dataset.matchSelect)%4],'stroke-width':2.5}))line.setAttribute(k,v);svg.append(line);});};
  root.querySelectorAll('.quiz-match-panel').forEach(panel=>{const observer=new ResizeObserver(()=>draw(panel));observer.observe(panel);observers.push(observer);requestAnimationFrame(()=>draw(panel));});
  const changed=el=>el.dispatchEvent(new Event('input',{bubbles:true}));
  root.addEventListener('focusin',ev=>{if(ev.target.matches('[data-gap]'))selectedGap=ev.target;});
  root.addEventListener('change',ev=>{if(ev.target.matches('[data-match-select]'))draw(ev.target.closest('.quiz-match-panel'));});
  root.addEventListener('click',ev=>{const b=ev.target.closest('[data-drag-word],[data-rank-move],[data-match-left],[data-match-right]');if(!b||b.disabled)return;const card=b.closest('[data-quiz-answer]');if(b.dataset.dragWord!==undefined){const gap=selectedGap&&card.contains(selectedGap)?selectedGap:[...card.querySelectorAll('[data-gap]')].find(x=>!x.value)||card.querySelector('[data-gap]');if(gap&&!gap.readOnly){gap.value=b.dataset.dragWord;changed(gap);gap.focus();}}else if(b.dataset.rankMove){const li=b.closest('li'),other=Number(b.dataset.rankMove)<0?li.previousElementSibling:li.nextElementSibling;if(other){Number(b.dataset.rankMove)<0?other.before(li):other.after(li);changed(li);}}else if(b.dataset.matchLeft!==undefined){selectedLeft=b;card.querySelectorAll('[data-match-left]').forEach(x=>x.classList.toggle('selected',x===b));}else if(selectedLeft&&card.contains(selectedLeft)){const sel=card.querySelector('[data-match-select="'+selectedLeft.dataset.matchLeft+'"]');sel.value=b.dataset.matchRight;changed(sel);draw(card.querySelector('.quiz-match-panel'));}});
  root.addEventListener('dragstart',ev=>{const el=ev.target.closest('[data-drag-word],[data-rank-item],[data-match-left]');if(!el||el.disabled)return;drag=el;ev.dataTransfer.setData('text/plain','quiz-item');ev.dataTransfer.effectAllowed='move';});
  root.addEventListener('dragover',ev=>{if(drag&&ev.target.closest('[data-gap],[data-rank-item],[data-match-right]'))ev.preventDefault();});
  root.addEventListener('drop',ev=>{const target=ev.target.closest('[data-gap],[data-rank-item],[data-match-right]');if(!target||!drag||target.closest('[data-quiz-answer]')!==drag.closest('[data-quiz-answer]'))return;ev.preventDefault();if(target.matches('[data-gap]')&&drag.dataset.dragWord!==undefined&&!target.readOnly){target.value=drag.dataset.dragWord;changed(target);}else if(target.matches('[data-rank-item]')&&drag.matches('[data-rank-item]')){const box=target.getBoundingClientRect();ev.clientY>box.top+box.height/2?target.after(drag):target.before(drag);changed(target);}else if(target.dataset.matchRight!==undefined&&drag.dataset.matchLeft!==undefined){const card=target.closest('[data-quiz-answer]'),sel=card.querySelector('[data-match-select="'+drag.dataset.matchLeft+'"]');if(!sel.disabled){sel.value=target.dataset.matchRight;changed(sel);draw(card.querySelector('.quiz-match-panel'));}}drag=null;});
 }
 return{extra,config,readConfig,common,imageHTML,studentWidget,readAnswer,answerText,filesFromInput,bindStudent,mathText,mathHTML};
}
